	/** 
	 * jumpstart the process by instantiating2 Catalog
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		catalogId = CatalogService.getCatalogInstance()
		.createCatalog( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CatalogService.getCatalogInstance()
				.createCatalog( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.catalogSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Catalog : " + successValue.getCatalogId());
							  if (successValue.getCatalogId().equals(catalogId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCatalogList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Catalog test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on catalog consumed")
					);
			subscriber.catalogSubscribe( catalogId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Catalog : " + successValue.getCatalogId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCatalogList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on catalog for catalogId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Catalog. 
	 */
	protected Catalog read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Catalog" );

		Catalog entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Catalog with primary key" );
		msg.append( catalogId );
		
		CatalogFetchOneSummary fetchOneSummary = new CatalogFetchOneSummary( catalogId );

		try {
			entity = CatalogService.getCatalogInstance().getCatalog( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Catalog " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Catalog.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Catalog." );

		StringBuilder msg = new StringBuilder( "Failed to update a Catalog : " );        
		Catalog entity = read();
		UpdateCatalogCommand command = generateUpdateCommand();
		command.setCatalogId(entity.getCatalogId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Catalog." );

			// for use later on...
			catalogId = entity.getCatalogId();

			CatalogService proxy = CatalogService.getCatalogInstance();  

			proxy.updateCatalog( command ).get();

			LOGGER.info( "-- Successfully saved Catalog - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + catalogId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Catalog.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Catalog." );

		Catalog entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Catalog with id " + catalogId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Catalog with id " + catalogId );

			throw e;
		}

		try{
			CatalogService.getCatalogInstance().delete( new DeleteCatalogCommand( entity.getCatalogId() ) ).get();
			LOGGER.info( "-- Successfully deleted Catalog with id " + catalogId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Catalog with id " + catalogId );

			throw e;
		}
	}

	/**
	 * get all Catalogs.
	 */
	protected List<Catalog> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Catalogs:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Catalog : " );        
		List<Catalog> collection  = new ArrayList<>();

		try {
			// call the static get method on the CatalogService
			collection = CatalogService.getCatalogInstance().getAllCatalog();
			assertNotNull( collection, "An Empty collection of Catalog was incorrectly returned.");
			
			// Now print out the values
			Catalog entity = null;            
			Iterator<Catalog> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCatalogId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

